function closeServices(services: ServiceRegistry, log: Logger): void {
  const close = (name: string, svc: { close: () => void }) => {
    try { svc.close(); } catch (err) { log.warn('close', `Failed to close ${name}: ${String(err)}`); }
  };
  close('memory', services.memory);
  close('rosterContext', services.rosterContext);
  close('analytics', services.analytics);
  if (services.extractEmbedCache) close('extractEmbedCache', services.extractEmbedCache);
  if (services.retrieveCache) close('retrieveCache', services.retrieveCache);
}
